/// <summary>
/// Handles insert, update and delete events for <c>EcoResProductAttributeValue</c>.
/// When the changed attribute matches the priced-by-weight attribute recId,
/// clears the <c>METPricedByWeight</c> entry from the global object cache for this AOS.
/// </summary>
/// <param name="sender">The record that raised the event (an <c>EcoResProductAttributeValue</c>).</param>
/// <param name="e">Event arguments (<c>DataEventArgs</c>).</param>
public class METEcoResProductAttributeValue_EventHandler
{
}

Method.Source:
/// <summary>
/// Handles insert, update and delete events for <c>EcoResProductAttributeValue</c>.
/// When the changed attribute matches the priced-by-weight attribute recId,
/// clears the <c>METPricedByWeight</c> entry from the global object cache for this AOS.
/// </summary>
/// <param name="sender">The record that raised the event (an <c>EcoResProductAttributeValue</c>).</param>
/// <param name="e">Event arguments (<c>DataEventArgs</c>).</param>
[DataEventHandler(tableStr(EcoResProductAttributeValue), DataEventType::Updated),
 DataEventHandler(tableStr(EcoResProductAttributeValue), DataEventType::Inserted),
 DataEventHandler(tableStr(EcoResProductAttributeValue), DataEventType::Deleted)]
public static void EcoResProductAttributeValue_onChange(Common sender, DataEventArgs e)
{
    EcoResProductAttributeValue productAttributeValue = sender;

    if (productAttributeValue.Attribute == METPricedByWeightCache::pricedByWeightAttributeRecId())
        classFactory.globalObjectCache().clear(METConstants::METPricedByWeight);   // evict scope (this AOS)
}
